// Match only unambiguous exact titles; never use popularity as identity evidence.
const normalizeTitle = s => String(s||'').normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');
function chooseCandidate(record,data){
 const title=normalizeTitle(record.title),year=(record.meta||'').match(/((?:19|20)\d{2})年製作/)?.[1];
 if(data.total_pages>1)return {reason:'候補が多いため要確認'};
 const exact=(data.results||[]).filter(m=>[m.title,m.original_title].some(t=>normalizeTitle(t)===title));
 const candidates=year?exact.filter(m=>m.release_date?.slice(0,4)===year):exact;
 if(candidates.length!==1)return {reason:candidates.length>1?'同名作品の候補が複数':'作品名・公開年の完全一致なし'};
 if(!year&&title.length<=3)return {reason:'短い作品名・公開年なしのため要確認'};
 return {candidate:candidates[0],evidence:year?'作品名と製作年が完全一致':'作品名が完全一致・全検索結果内で候補が1件'};
}
const txt=v=>typeof v==='string'?v:'';
function metadata(data){
 const now=Date.now(),jp=data['watch/providers']?.results?.JP,groups={};
 for(const k of ['flatrate','rent','buy','free','ads'])groups[k]=[...new Set((jp?.[k]||[]).map(p=>txt(p.provider_name)).filter(Boolean))];
 const dates=(data.release_dates?.results||[]).find(r=>r.iso_3166_1==='JP')?.release_dates||[];
 return {source:'TMDB',id:data.id,title:txt(data.title),originalTitle:txt(data.original_title),releaseDate:txt(data.release_date),japanTheatricalDate:dates.filter(r=>[2,3].includes(r.type)).map(r=>r.release_date.slice(0,10)).sort()[0]||'',runtime:data.runtime||null,directors:(data.credits?.crew||[]).filter(p=>p.job==='Director').map(p=>txt(p.name)),cast:(data.credits?.cast||[]).slice(0,12).map(p=>({name:txt(p.name),character:txt(p.character)})),genres:(data.genres||[]).map(g=>txt(g.name)),overview:txt(data.overview),poster:/^\/[\w.-]+$/.test(data.poster_path||'')?'https://image.tmdb.org/t/p/w500'+data.poster_path:'',checkedAt:now,providers:data['watch/providers']?{...groups,checkedAt:now,region:'JP',link:txt(jp?.link)}:null,providerError:!data['watch/providers']};
}
const protectedRecord = record => {const {movie,enrichment,_revision,...rest}=record;return rest;};
async function enrichBatch(request,env){
 const url=new URL(request.url);
 if(request.method==='GET'){
  const {results}=await env.DB.prepare('SELECT f.id,f.body,s.body AS original FROM films f LEFT JOIN enrichment_snapshots s ON f.id=s.id').all();
  let linked=0,review=0,errors=0,posters=0,protectedMismatch=0,processed=0;
  for(const row of results){const r=JSON.parse(row.body);if(r.enrichment){processed++;if(r.enrichment.status==='linked')linked++;else if(r.enrichment.status==='review')review++;else errors++;}if(r.movie?.poster)posters++;if(row.original&&JSON.stringify(protectedRecord(r))!==JSON.stringify(protectedRecord(JSON.parse(row.original))))protectedMismatch++;}
  return json({total:results.length,processed,linked,review,errors,posters,protectedMismatch});
 }
 if(request.method!=='POST')return json({error:'利用できません。'},405);
 const input=await request.json(),cursor=typeof input.cursor==='string'?input.cursor:'';
 const {results}=await env.DB.prepare('SELECT id,body,revision FROM films WHERE id > ? ORDER BY id LIMIT 5').bind(cursor).all();
 const key=await storedKey(env);if(!key)return json({error:'映画情報の共通接続が必要です。'},503);
 const outcomes=await Promise.all(results.map(async row=>{
  const record=JSON.parse(row.body);
  if(record.enrichment||record.movie?.id)return {id:row.id,status:'skip'};
  try{
   const search=await upstream('search/movie',key,[['query',record.title],['include_adult','false'],['region','JP']]);if(!search.ok)throw new Error('search');
   const data=await search.json(),match=chooseCandidate(record,data);let movie;
   if(match.candidate){const detail=await upstream('movie/'+match.candidate.id,key,[['append_to_response','credits,release_dates,watch/providers']]);if(!detail.ok)throw new Error('details');const d=await detail.json();if(d.id!==match.candidate.id)throw new Error('identity');movie=metadata(d);}
   const enrichment={status:movie?'linked':'review',reason:match.evidence||match.reason,checkedAt:Date.now(),candidates:movie?[]:(data.results||[]).filter(m=>normalizeTitle(m.title)===normalizeTitle(record.title)||normalizeTitle(m.original_title)===normalizeTitle(record.title)).slice(0,6).map(m=>({id:m.id,title:m.title,year:(m.release_date||'').slice(0,4)}))};
   const next={...record,...(movie?{movie}:{}),enrichment};
   // The snapshot and optimistic update are one transaction. Concurrent edits win.
   const saved=await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO enrichment_snapshots(id,body,revision) VALUES(?,?,?)').bind(row.id,row.body,row.revision),env.DB.prepare('UPDATE films SET body=?,revision=revision+1 WHERE id=? AND revision=?').bind(JSON.stringify(next),row.id,row.revision)]);
   return {id:row.id,status:saved[1].meta.changes===1?enrichment.status:'conflict'};
  }catch{return {id:row.id,status:'error'};}
 }));
 return json({cursor:results.at(-1)?.id||cursor,done:results.length<5,outcomes});
}

// Passphrase gate for the Cloudflare deployment (added at migration time).
// The app itself still checks for the ChatGPT Sites identity header; after a
// successful passphrase login this gate injects that header, so worker/api.mjs
// and the client stay unchanged. Active only when both AUTH_SECRET and
// AUTH_PASSPHRASE are set as Worker secrets; otherwise it is skipped.
async function yoinAuthToken(env) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(env.AUTH_SECRET), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode('yoin-owner-v1'));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, '0')).join('');
}
function yoinCookieValue(request, name) {
  const raw = request.headers.get('Cookie') || '';
  for (const part of raw.split(';')) {
    const i = part.indexOf('=');
    if (i > 0 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return '';
}
function yoinSame(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
function yoinLoginPage(error) {
  return `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>余韻 — ログイン</title><style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f6f3ec;font-family:sans-serif;color:#223}.card{background:#fff;border:1px solid #ddd6c4;border-radius:16px;padding:32px 28px;max-width:340px;width:88%;box-shadow:0 8px 30px rgba(60,50,20,.08)}h1{font-size:28px;margin:0 0 4px;letter-spacing:.2em}.sub{color:#667;font-size:13px;margin:0 0 20px}label{font-size:13px;color:#445;display:block;margin-bottom:6px}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #c9c2ae;border-radius:10px;font-size:16px}button{margin-top:16px;width:100%;padding:12px;border:0;border-radius:10px;background:#20503c;color:#fff;font-size:16px;cursor:pointer}.err{color:#a33;font-size:13px;margin:0 0 12px}</style></head><body><main class="card"><h1>余韻</h1><p class="sub">映画の記録 — 本人専用です</p>${error ? '<p class="err">合言葉が違います。もう一度お試しください。</p>' : ''}<form method="post" action="/login"><label for="p">合言葉</label><input id="p" name="passphrase" type="password" autocomplete="current-password" required autofocus><button type="submit">開く</button></form></main></body></html>`;
}
async function yoinGate(request, env, path) {
  if (path === '/login') {
    if (request.method === 'POST') {
      const form = await request.formData().catch(() => null);
      const pass = form ? String(form.get('passphrase') || '') : '';
      if (yoinSame(pass, env.AUTH_PASSPHRASE)) {
        const token = await yoinAuthToken(env);
        return new Response(null, { status: 303, headers: { 'Location': '/', 'Set-Cookie': 'yoin_auth=' + token + '; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=15552000', 'Cache-Control': 'no-store' } });
      }
      return new Response(yoinLoginPage(true), { status: 401, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
    }
    return new Response(yoinLoginPage(false), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
  }
  if (path === '/logout') {
    return new Response(null, { status: 303, headers: { 'Location': '/login', 'Set-Cookie': 'yoin_auth=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0', 'Cache-Control': 'no-store' } });
  }
  // /api/bot/* is authenticated by its own bearer token inside botApi() (worker/bot-api.mjs),
  // never by the cookie; the bearer token is not accepted anywhere else.
  if (path.startsWith('/api/bot/')) return request;
  const token = await yoinAuthToken(env);
  if (yoinSame(yoinCookieValue(request, 'yoin_auth'), token)) {
    const headers = new Headers(request.headers);
    headers.set('oai-authenticated-user-id', 'owner');
    return new Request(request, { headers });
  }
  if (path.startsWith('/api/')) return Response.json({ error: 'ログインが必要です。ページを開き直してログインしてください。' }, { status: 401, headers: { 'Cache-Control': 'no-store' } });
  return new Response(yoinLoginPage(false), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
}

// Scoped API for the owner's chat bot (/api/bot/*).
// Authenticated ONLY by `Authorization: Bearer <BOT_API_TOKEN>` (Worker secret).
// The token is never accepted on any other path, and this API can only search,
// list, create and partially update records — no delete, import, TMDB
// connection or enrichment. Created records use the same shape as the UI.
const BOT_FIELDS = ['status', 'rating', 'date', 'review', 'meta'];
const botJson = (data, status = 200) => Response.json(data, {status, headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function botAuthorized(request, env) {
  const token = typeof env.BOT_API_TOKEN === 'string' ? env.BOT_API_TOKEN : '';
  if (token.length < 32) return 'unconfigured';
  const header = request.headers.get('Authorization') || '';
  const m = /^Bearer\s+(\S+)$/.exec(header);
  return m && yoinSame(m[1], token) ? 'ok' : 'denied';
}
// Same rules as client/app.js validateRecords(), so bot records never break the UI.
function botClientValid(r) {
  if (!validate(r) || Math.abs(r.rating * 10 - Math.round(r.rating * 10)) > 0.000001) return false;
  const m = r.movie;
  if (m != null) {
    if (m.source !== 'TMDB' || !Number.isInteger(m.id) || m.id < 1 || (m.mediaType != null && !['movie', 'tv'].includes(m.mediaType)) || (m.seasons != null && !Number.isInteger(m.seasons)) || (m.episodes != null && !Number.isInteger(m.episodes)) || ['title', 'originalTitle', 'releaseDate', 'japanTheatricalDate', 'overview', 'poster'].some(k => typeof m[k] !== 'string') || !Number.isFinite(m.checkedAt) || !Array.isArray(m.directors) || !Array.isArray(m.genres) || [...m.directors, ...m.genres].some(x => typeof x !== 'string')) return false;
    if (m.cast != null && (!Array.isArray(m.cast) || m.cast.some(p => !p || typeof p.name !== 'string' || typeof p.character !== 'string'))) return false;
    if (m.providers != null) {
      const p = m.providers;
      if (p.region !== 'JP' || !Number.isFinite(p.checkedAt) || typeof p.link !== 'string' || ['flatrate', 'rent', 'buy', 'free', 'ads'].some(k => !Array.isArray(p[k]) || p[k].some(x => typeof x !== 'string'))) return false;
    }
  }
  return true;
}
// Field checks for bot input. Returns an error message or ''.
function botFieldError(data) {
  if ('status' in data && !['watched', 'want'].includes(data.status)) return 'status は "watched" か "want" を指定してください。';
  if ('rating' in data && (typeof data.rating !== 'number' || !Number.isFinite(data.rating) || data.rating < 0 || data.rating > 5 || Math.abs(data.rating * 10 - Math.round(data.rating * 10)) > 0.000001)) return 'rating は 0〜5 の数値（小数第1位まで、0 は未評価）で指定してください。';
  if ('date' in data && (typeof data.date !== 'string' || (data.date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(data.date)))) return 'date は "YYYY-MM-DD" か空文字で指定してください。';
  for (const k of ['review', 'meta']) if (k in data && (typeof data[k] !== 'string' || data[k].length > 100000)) return k + ' は文字列で指定してください。';
  return '';
}
const botDate = v => /^\d{4}-\d{2}-\d{2}/.test(v || '') ? v.slice(0, 10) : '';
const botText = v => typeof v === 'string' ? v : '';
const botImage = p => /^\/[a-zA-Z0-9_.-]+$/.test(p || '') ? 'https://image.tmdb.org/t/p/w500' + p : '';
const botNormalize = s => String(s || '').normalize('NFKC').replace(/\s+/g, '').toLowerCase();
class BotTmdbError extends Error { constructor(status, message) { super(message); this.status = status; } }
async function botTmdb(env, key, path, params = []) {
  let result;
  try { result = await upstream(path, key, params); } catch { throw new BotTmdbError(503, '映画情報に接続できませんでした。時間をおいて再度お試しください。'); }
  if (result.status === 404) throw new BotTmdbError(404, 'TMDBに該当する作品がありません。');
  if (!result.ok) throw new BotTmdbError(result.status === 429 ? 429 : 502, result.status === 429 ? '検索が混み合っています。少し待って再度お試しください。' : '映画情報を取得できませんでした。');
  return result.json();
}
async function botKey(env) {
  if (!env.TMDB_CONFIG_KEY) throw new BotTmdbError(503, '共通接続を準備しています。');
  const key = await storedKey(env);
  if (!key) throw new BotTmdbError(503, '映画情報を接続してください。');
  return key;
}
// Port of FilmAPI.normalizeProviders / FilmAPI.details in client/films-api.js.
function botProviders(data, checkedAt, media) {
  const jp = data.results?.JP, groups = {};
  for (const k of ['flatrate', 'rent', 'buy', 'free', 'ads']) groups[k] = [...new Set((jp?.[k] || []).map(p => botText(p.provider_name)).filter(Boolean))];
  const linkPattern = media === 'tv' ? /^https:\/\/www\.themoviedb\.org\/tv\// : /^https:\/\/www\.themoviedb\.org\/movie\//;
  return { ...groups, checkedAt, region: 'JP', link: linkPattern.test(jp?.link || '') ? jp.link : '' };
}
async function botDetails(env, key, id, media) {
  const [result, providers] = await Promise.allSettled([
    botTmdb(env, key, media + '/' + id, [['append_to_response', media === 'tv' ? 'credits' : 'credits,release_dates']]),
    botTmdb(env, key, media + '/' + id + '/watch/providers')
  ]);
  if (result.status !== 'fulfilled') throw result.reason;
  const data = result.value, now = Date.now();
  if (data.id !== id) throw new BotTmdbError(502, '映画情報を取得できませんでした。');
  const normalized = providers.status === 'fulfilled' ? botProviders(providers.value, now, media) : null;
  const cast = (data.credits?.cast || []).slice(0, 12).map(p => ({ name: botText(p.name), character: botText(p.character) }));
  const genres = (data.genres || []).map(g => botText(g.name)).filter(Boolean);
  if (media === 'tv') {
    const runTimes = (data.episode_run_time || []).filter(t => Number.isFinite(t) && t > 0);
    return {
      source: 'TMDB', id, mediaType: 'tv', title: botText(data.name), originalTitle: botText(data.original_name),
      releaseDate: botDate(data.first_air_date), japanTheatricalDate: '',
      runtime: runTimes.length ? Math.round(runTimes.reduce((a, b) => a + b, 0) / runTimes.length) : null,
      seasons: Number.isInteger(data.number_of_seasons) && data.number_of_seasons > 0 ? data.number_of_seasons : null,
      episodes: Number.isInteger(data.number_of_episodes) && data.number_of_episodes > 0 ? data.number_of_episodes : null,
      directors: (data.created_by || []).map(p => botText(p.name)).filter(Boolean),
      cast, genres, overview: botText(data.overview), poster: botImage(data.poster_path), checkedAt: now,
      providers: normalized, providerError: providers.status === 'rejected'
    };
  }
  const jpDates = (data.release_dates?.results || []).find(r => r.iso_3166_1 === 'JP')?.release_dates || [];
  const theatricalDates = jpDates.filter(r => [2, 3].includes(r.type)).map(r => botDate(r.release_date)).filter(Boolean).sort();
  return {
    source: 'TMDB', id, mediaType: 'movie', title: botText(data.title), originalTitle: botText(data.original_title),
    releaseDate: botDate(data.release_date), japanTheatricalDate: theatricalDates[0] || '',
    runtime: Number.isFinite(data.runtime) && data.runtime > 0 ? data.runtime : null,
    directors: (data.credits?.crew || []).filter(p => p.job === 'Director').map(p => botText(p.name)).filter(Boolean),
    cast, genres, overview: botText(data.overview), poster: botImage(data.poster_path), checkedAt: now,
    providers: normalized, providerError: providers.status === 'rejected'
  };
}
async function botShelf(env) {
  const {results} = await env.DB.prepare('SELECT body, revision FROM films ORDER BY id').all();
  return results.map(r => ({...JSON.parse(r.body), _revision: r.revision}));
}
const botMedia = r => r.movie?.mediaType || 'movie';
const botBrief = r => ({ id: r.id, title: r.title, status: r.status, rating: r.rating, date: r.date, _revision: r._revision });
// Same matching as findFilmRecord() in client/app.js.
function botFindOnShelf(shelf, film) {
  const exact = shelf.find(r => r.movie?.id === film.id && botMedia(r) === film.mediaType);
  if (exact) return { match: 'tmdb', record: exact };
  const year = (film.releaseDate || '').slice(0, 4);
  const compatible = shelf.filter(r => botNormalize(r.title) === botNormalize(film.title)).filter(r => { const known = (r.meta || '').match(/(19\d{2}|20\d{2})年製作/); return !known || !year || known[1] === year; });
  const record = compatible.find(r => r.status === 'watched') || compatible[0];
  return record ? { match: 'title', record } : null;
}
async function botSearch(url, env) {
  const query = (url.searchParams.get('query') || url.searchParams.get('q') || '').trim();
  if (!query || query.length > 200) return botJson({error: 'query を指定してください。'}, 400);
  const key = await botKey(env);
  const [movies, shows] = await Promise.allSettled([
    botTmdb(env, key, 'search/movie', [['query', query], ['region', 'JP'], ['include_adult', 'false']]),
    botTmdb(env, key, 'search/tv', [['query', query], ['include_adult', 'false']])
  ]);
  const list = (res, mediaType) => res.status === 'fulfilled' ? (res.value.results || []).filter(i => Number.isInteger(i.id) && i.id > 0).map(i => ({
    tmdbId: i.id, mediaType, title: botText(i.title || i.name), originalTitle: botText(i.original_title || i.original_name),
    releaseDate: botDate(i.release_date || i.first_air_date), overview: botText(i.overview).slice(0, 160), poster: botImage(i.poster_path),
    popularity: Number.isFinite(i.popularity) ? i.popularity : 0
  })) : [];
  const merged = [...list(movies, 'movie'), ...list(shows, 'tv')];
  if (!merged.length && movies.status === 'rejected') throw movies.reason;
  if (!merged.length && shows.status === 'rejected') throw shows.reason;
  merged.sort((a, b) => b.popularity - a.popularity);
  const shelf = await botShelf(env);
  const limit = Math.min(40, Math.max(1, Number(url.searchParams.get('limit')) || 20));
  return botJson({results: merged.slice(0, limit).map(({popularity, ...film}) => {
    const found = botFindOnShelf(shelf, {id: film.tmdbId, mediaType: film.mediaType, title: film.title, releaseDate: film.releaseDate});
    return {...film, year: film.releaseDate.slice(0, 4), onShelf: found ? {match: found.match, ...botBrief(found.record)} : null};
  })});
}
async function botList(url, env) {
  const q = (url.searchParams.get('q') || '').toLowerCase(), status = url.searchParams.get('status') || '';
  const tmdbId = url.searchParams.get('tmdbId'), mediaType = url.searchParams.get('mediaType') || '';
  if (status && !['watched', 'want'].includes(status)) return botJson({error: 'status は watched か want です。'}, 400);
  if (mediaType && !['movie', 'tv'].includes(mediaType)) return botJson({error: 'mediaType は movie か tv です。'}, 400);
  if (tmdbId != null && !/^[1-9]\d{0,9}$/.test(tmdbId)) return botJson({error: 'tmdbId が不正です。'}, 400);
  const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit')) || 50));
  const matches = (await botShelf(env)).filter(r =>
    (!status || r.status === status) &&
    (tmdbId == null || r.movie?.id === Number(tmdbId)) &&
    (!mediaType || botMedia(r) === mediaType) &&
    (!q || [r.title, r.movie?.title, r.movie?.originalTitle].some(t => typeof t === 'string' && t.toLowerCase().includes(q)))
  ).sort((a, b) => b.updated - a.updated);
  return botJson({total: matches.length, records: matches.slice(0, limit)});
}
async function botCreate(request, env) {
  const data = await request.json().catch(() => null);
  if (!data || typeof data !== 'object' || Array.isArray(data)) return botJson({error: 'JSON の本文が必要です。'}, 400);
  if (!('status' in data)) return botJson({error: 'status を指定してください。'}, 400);
  const fieldError = botFieldError(data);
  if (fieldError) return botJson({error: fieldError}, 400);
  if (data.title != null && (typeof data.title !== 'string' || data.title.length > 1000)) return botJson({error: 'title が不正です。'}, 400);
  let movie = null;
  if (data.tmdbId != null) {
    if (!Number.isInteger(data.tmdbId) || data.tmdbId < 1) return botJson({error: 'tmdbId が不正です。'}, 400);
    const media = data.mediaType == null ? 'movie' : data.mediaType;
    if (!['movie', 'tv'].includes(media)) return botJson({error: 'mediaType は movie か tv です。'}, 400);
    const existing = (await botShelf(env)).find(r => r.movie?.id === data.tmdbId && botMedia(r) === media);
    if (existing) return botJson({error: 'この作品はすでに棚にあります。', record: existing}, 409);
    movie = await botDetails(env, await botKey(env), data.tmdbId, media);
  }
  const title = (typeof data.title === 'string' && data.title.trim()) ? data.title.trim() : (movie?.title || movie?.originalTitle || '');
  if (!title) return botJson({error: 'title か tmdbId を指定してください。'}, 400);
  if (!movie && data.allowDuplicateTitle !== true) {
    const same = (await botShelf(env)).find(r => botNormalize(r.title) === botNormalize(title));
    if (same) return botJson({error: '同じ作品名の記録がすでにあります。別作品として追加する場合は allowDuplicateTitle: true を指定してください。', record: same}, 409);
  }
  const record = {
    id: crypto.randomUUID(), title, status: data.status,
    rating: data.rating ?? 0, date: data.date ?? '', meta: (data.meta ?? '').trim(), review: (data.review ?? '').trim(),
    updated: Date.now(), ...(movie ? {movie} : {})
  };
  if (!botClientValid(record)) return botJson({error: '記録の形式が正しくありません。'}, 400);
  const body = JSON.stringify(record);
  // Atomic duplicate guard: insert only if no record already has this TMDB id + media type.
  const result = movie
    ? await env.DB.prepare("INSERT INTO films (id, body, revision) SELECT ?, ?, 1 WHERE NOT EXISTS (SELECT 1 FROM films WHERE json_extract(body, '$.movie.id') = ? AND coalesce(json_extract(body, '$.movie.mediaType'), 'movie') = ?)").bind(record.id, body, movie.id, movie.mediaType).run()
    : await env.DB.prepare('INSERT INTO films (id, body, revision) VALUES (?, ?, 1)').bind(record.id, body).run();
  if (result.meta.changes !== 1) {
    const existing = (await botShelf(env)).find(r => r.movie?.id === movie.id && botMedia(r) === movie.mediaType);
    return botJson({error: 'この作品はすでに棚にあります。', record: existing || null}, 409);
  }
  return botJson({record: {...record, _revision: 1}}, 201);
}
async function botUpdate(request, env, id) {
  const data = await request.json().catch(() => null);
  if (!data || typeof data !== 'object' || Array.isArray(data)) return botJson({error: 'JSON の本文が必要です。'}, 400);
  if (!Number.isInteger(data._revision) || data._revision < 1) return botJson({error: '_revision を指定してください。'}, 409);
  const extra = Object.keys(data).filter(k => k !== '_revision' && !BOT_FIELDS.includes(k));
  if (extra.length) return botJson({error: '変更できない項目です: ' + extra.join(', ') + '（変更できるのは ' + BOT_FIELDS.join(', ') + '）'}, 400);
  if (!BOT_FIELDS.some(k => k in data)) return botJson({error: '変更する項目を指定してください。'}, 400);
  const fieldError = botFieldError(data);
  if (fieldError) return botJson({error: fieldError}, 400);
  const row = await env.DB.prepare('SELECT body, revision FROM films WHERE id = ?').bind(id).first();
  if (!row) return botJson({error: '記録が見つかりません。'}, 404);
  const current = JSON.parse(row.body);
  if (row.revision !== data._revision) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。', record: {...current, _revision: row.revision}}, 409);
  const next = {...current, updated: Date.now()};
  for (const k of BOT_FIELDS) if (k in data) next[k] = (k === 'review' || k === 'meta') ? data[k].trim() : data[k];
  if (!botClientValid(next)) return botJson({error: '記録の形式が正しくありません。'}, 400);
  const result = await env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(next), id, data._revision).run();
  if (result.meta.changes !== 1) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。'}, 409);
  return botJson({record: {...next, _revision: data._revision + 1}});
}
async function botApi(request, env) {
  const auth = botAuthorized(request, env);
  if (auth === 'unconfigured') return botJson({error: 'ボット用APIは設定されていません。'}, 503);
  if (auth !== 'ok') return Response.json({error: 'ボット用の鍵が必要です。'}, {status: 401, headers: {'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'WWW-Authenticate': 'Bearer'}});
  if (!env.DB) return botJson({error: '保存先の準備が完了していません。'}, 503);
  const url = new URL(request.url), path = url.pathname, method = request.method;
  if (method !== 'GET' && !request.headers.get('Content-Type')?.startsWith('application/json')) return botJson({error: 'Content-Type: application/json で送ってください。'}, 415);
  try {
    if (path === '/api/bot/search') return method === 'GET' ? await botSearch(url, env) : botJson({error: 'この操作は利用できません。'}, 405);
    if (path === '/api/bot/records') {
      if (method === 'GET') return await botList(url, env);
      if (method === 'POST') return await botCreate(request, env);
      return botJson({error: 'この操作は利用できません。'}, 405);
    }
    const m = /^\/api\/bot\/records\/([^/]+)$/.exec(path);
    if (m) {
      let id;
      try { id = decodeURIComponent(m[1]); } catch { return botJson({error: 'IDが不正です。'}, 400); }
      if (!id || id.length > 200) return botJson({error: 'IDが不正です。'}, 400);
      if (method === 'GET') { const row = await env.DB.prepare('SELECT body, revision FROM films WHERE id = ?').bind(id).first(); return row ? botJson({record: {...JSON.parse(row.body), _revision: row.revision}}) : botJson({error: '記録が見つかりません。'}, 404); }
      if (method === 'PATCH') return await botUpdate(request, env, id);
      return botJson({error: 'この操作は利用できません。'}, 405);
    }
    return botJson({error: '見つかりません。'}, 404);
  } catch (e) {
    if (e instanceof BotTmdbError) return botJson({error: e.message}, e.status);
    return botJson({error: '処理できませんでした。時間をおいて再度お試しください。'}, 503);
  }
}

const json = (data, status = 200) => Response.json(data, {status, headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function validate(r) {
  return r && typeof r.id==='string' && r.id.length>0 && r.id.length<=200 && typeof r.title==='string' && r.title.trim() && r.title.length<=1000 && ['watched','want'].includes(r.status) && Number.isFinite(r.rating) && r.rating>=0 && r.rating<=5 && Number.isFinite(r.updated) && ['date','meta','review'].every(k=>typeof r[k]==='string' && r[k].length<=100000);
}
function clean(r) { const {_revision,...body}=r; return body; }
async function api(request, env) {
  if(new URL(request.url).pathname.startsWith('/api/bot/'))return botApi(request,env);
  if(!request.headers.get('oai-authenticated-user-id'))return json({error:'同じChatGPTアカウントでログインしてください。'},401);
  if(new URL(request.url).pathname.startsWith('/api/tmdb'))return tmdb(request,env);
  if(!env.DB)return json({error:'保存先の準備が完了していません。'},503);
  const url=new URL(request.url);
  if(request.method!=='GET' && (request.headers.get('Origin')!==url.origin || !request.headers.get('Content-Type')?.startsWith('application/json')))return json({error:'この画面から操作してください。'},403);
  try {
    if(url.pathname==='/api/enrich')return await enrichBatch(request,env);
    if(url.pathname==='/api/records' && request.method==='GET') {
      const {results}=await env.DB.prepare('SELECT body, revision FROM films ORDER BY id').all();
      return json({records:results.map(r=>({...JSON.parse(r.body),_revision:r.revision}))});
    }
    if(url.pathname==='/api/import' && request.method==='POST') {
      const data=await request.json();
      if(!Array.isArray(data.records)||data.records.length>10000||!data.records.every(validate)||new Set(data.records.map(r=>r.id)).size!==data.records.length)return json({error:'記録の形式が正しくありません。'},400);
      let added=0;
      for(let i=0;i<data.records.length;i+=50){
        const results=await env.DB.batch(data.records.slice(i,i+50).map(r=>env.DB.prepare('INSERT OR IGNORE INTO films (id, body, revision) VALUES (?, ?, 1)').bind(r.id,JSON.stringify(clean(r)))));
        added+=results.reduce((n,r)=>n+(r.meta?.changes||0),0);
      }
      return json({added});
    }
    if(url.pathname.startsWith('/api/records/')) {
      const id=decodeURIComponent(url.pathname.slice('/api/records/'.length));const data=await request.json();
      if(!Number.isInteger(data._revision)||data._revision<1)return json({error:'最新の画面を開き直してから編集してください。'},409);
      let result;
      if(request.method==='PUT') {
        if(!validate(data)||data.id!==id)return json({error:'記録の形式が正しくありません。'},400);
        result=await env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(clean(data)),id,data._revision).run();
      }else if(request.method==='DELETE') {
        result=await env.DB.prepare('DELETE FROM films WHERE id = ? AND revision = ?').bind(id,data._revision).run();
      }else return json({error:'この操作は利用できません。'},405);
      if(result.meta.changes!==1)return json({error:'別の端末で更新されています。この画面を開き直してから編集してください。入力中の感想はコピーして残せます。'},409);
      return json({saved:true});
    }
    return json({error:'見つかりません。'},404);
  }catch(e){return json({error:'同期できませんでした。通信状態を確認してもう一度お試しください。'},503);}
}

const TMDB_HOST='https://api.themoviedb.org/3/';
async function cipherKey(env){return crypto.subtle.importKey('raw',Uint8Array.from(atob(env.TMDB_CONFIG_KEY),c=>c.charCodeAt(0)), 'AES-GCM',false,['encrypt','decrypt']);}
async function storedKey(env){const row=await env.DB.prepare("SELECT body FROM app_settings WHERE name = 'tmdb'").first();if(!row)return '';const data=JSON.parse(row.body);return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:Uint8Array.from(data.iv)},await cipherKey(env),Uint8Array.from(data.data)));}
async function upstream(path,key,params){const target=new URL(TMDB_HOST+path);target.searchParams.set('language','ja-JP');for(const [k,v] of params)if(['query','region','include_adult','include_video','page','watch_region','with_watch_providers','with_watch_monetization_types','sort_by','append_to_response','with_release_type','release_date.gte','release_date.lte','with_genres','without_genres','with_original_language','first_air_date.gte','first_air_date.lte','air_date.gte','air_date.lte'].includes(k)&&v.length<=300)target.searchParams.set(k,v);const headers={accept:'application/json'};if(/^[a-f0-9]{32}$/i.test(key))target.searchParams.set('api_key',key);else headers.Authorization='Bearer '+key;return fetch(target,{headers,signal:AbortSignal.timeout(15000)});}
// Calendar arithmetic uses the Tokyo calendar date, independent of server timezone.
function japanWeek(now = new Date()) {
 const today = new Date(now.toLocaleDateString('en-CA', {timeZone:'Asia/Tokyo'}) + 'T00:00:00Z');
 const monday = new Date(today);
 monday.setUTCDate(today.getUTCDate() - (today.getUTCDay() + 6) % 7);
 const sunday = new Date(monday);
 sunday.setUTCDate(monday.getUTCDate() + 6);
 return {start:monday.toISOString().slice(0,10),end:sunday.toISOString().slice(0,10)};
}
async function tmdb(request,env){
 const url=new URL(request.url);
 try{
  if(!env.DB||!env.TMDB_CONFIG_KEY)return json({error:'共通接続を準備しています。'},503);
  if(url.pathname==='/api/tmdb/connection'){
   if(request.method==='GET')return json({connected:!!(await storedKey(env))});
   if(request.method!=='POST'||request.headers.get('Origin')!==url.origin||!request.headers.get('Content-Type')?.startsWith('application/json'))return json({error:'この画面から操作してください。'},403);
   const data=await request.json();const key=typeof data.credential==='string'?data.credential.trim():'';
   if(!key||key.length>4096)return json({error:'接続キーを確認してください。'},400);
   const check=await upstream('configuration',key,[]);if(!check.ok)return json({error:'TMDBの接続キーを確認してください。'},400);
   const iv=crypto.getRandomValues(new Uint8Array(12));const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},await cipherKey(env),new TextEncoder().encode(key));
   await env.DB.prepare("INSERT INTO app_settings(name,body) VALUES('tmdb',?) ON CONFLICT(name) DO UPDATE SET body=excluded.body").bind(JSON.stringify({iv:[...iv],data:[...new Uint8Array(encrypted)]})).run();return json({connected:true});
  }
  if(request.method!=='GET')return json({error:'利用できません。'},405);
  let path=url.pathname.slice('/api/tmdb/'.length);
  let params=url.searchParams;
  if(path==='catalog/week'){
   const week=japanWeek();
   path='discover/movie';
   params=new URLSearchParams({page:params.get('page')||'1',region:'JP',with_release_type:'3|2','release_date.gte':week.start,'release_date.lte':week.end,sort_by:'release_date.asc',include_adult:'false',include_video:'false'});
  }
  if(!/^(configuration|search\/(?:movie|tv)|discover\/(?:movie|tv)|movie\/now_playing|trending\/(?:movie|tv)\/week|watch\/providers\/(?:movie|tv)|(?:movie|tv)\/[1-9]\d*(?:\/watch\/providers)?)$/.test(path))return json({error:'見つかりません。'},404);
  const key=await storedKey(env);if(!key)return json({error:'映画情報を接続してください。'},503);
  const result=await upstream(path,key,params);if(!result.ok)return json({error:result.status===429?'検索が混み合っています。少し待って再度お試しください。':'映画情報を取得できませんでした。'},result.status===429?429:502);
  return json(await result.json());
 }catch{return json({error:'映画情報に接続できませんでした。時間をおいて再度お試しください。'},503);}
}

